import java.rmi.NotBoundException;
import java.rmi.RemoteException;
import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.util.Objects;

public class Client {
    public static void main(String[] args) throws RemoteException, NotBoundException {
        String FN_ID;
        try {
            String ip = args[0];
            String port = args[1];
            FN_ID = args[2];


            Registry rmiRegistry = LocateRegistry.getRegistry(ip, Integer.parseInt(port));

            if (Objects.equals(FN_ID, "1")) {
                Account_managerInt stub3 = (Account_managerInt) rmiRegistry.lookup("C-Account");
                if (stub3.Create_Account(args[3]).equals("user created")) {
                    System.out.println("Account Created:" + stub3.getAuth_Token());
                } else {
                    System.out.println("Problem");
                }
            }

            if (Objects.equals(FN_ID, "2")) {
                String authToken = args[3];
                Account_managerInt stub = (Account_managerInt) rmiRegistry.lookup("C-Account");
                if (authenticate(stub, Integer.parseInt(authToken))) {
                    System.out.println("Accounts:");
                    String[] accounts = stub.showAccounts();
                    for (int i = 0; i < accounts.length; i++) {
                        System.out.println((i + 1) + ". " + accounts[i]);
                    }
                } else {
                    System.out.println("Authentication failed.");
                }
            }

            if (Objects.equals(FN_ID, "3")) {
                String authToken = args[3];
                String recipient = args[4];
                String messageBody = args[5];

                Account_managerInt stub = (Account_managerInt) rmiRegistry.lookup("C-Account");
                if (authenticate(stub, Integer.parseInt(authToken))) {
                    if (sendMessage(stub, recipient, messageBody)) {
                        System.out.println("OK");
                    } else {
                        System.out.println("User does not exist");
                    }
                } else {
                    System.out.println("Authentication failed.");
                }
            }
        } catch (RemoteException e) {
            throw new RuntimeException(e);
        } catch (NotBoundException e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean authenticate(Account_managerInt stub, int authToken) throws RemoteException {
        return stub.authenticate(authToken);
    }

    private static boolean sendMessage(Account_managerInt stub, String recipient, String messageBody) throws RemoteException {
        return stub.sendMessage(recipient, messageBody);
    }
}

